import '@aztec/aztec.js/abi';

declare module '@aztec/aztec.js/abi' {
  /**
   * Compatibility shim for Aztec contract wrappers generated by the v4.2.x CLI.
   * The generated TypeScript references OptionLike for Noir Option<T> values,
   * but @aztec/aztec.js@4.2.1 no longer exports that helper type.
   */
  export type OptionLike<T> =
    | { is_some: boolean; value?: T }
    | { isSome: boolean; value?: T }
    | T
    | null
    | undefined;
}
